import { useEffect, useMemo, useState } from 'react'
import type { ReactNode } from 'react'

type Screen = 'public' | 'request' | 'admin' | 'members' | 'memberships' | 'payments' | 'attendance' | 'leads' | 'reports' | 'member-portal' | 'member-attendance' | 'member-payments' | 'member-membership'
type Modal = 'add-member' | 'follow-up' | 'payment' | 'attendance' | 'renew' | 'request' | null

type Member = {
  id: number
  name: string
  phone: string
  status: 'فعال' | 'رو به پایان' | 'منقضی' | 'بدهکار' | 'غیرفعال'
  plan: string
  expiry: string
  lastVisit: string
  visits: number
  locker: string
  joined: string
  avatar: string
}

type Lead = { id: number; name: string; phone: string; plan: string; created: string; status: 'جدید' | 'در حال پیگیری' | 'تبدیل شده' }

type Toast = { id: number; message: string; type?: 'success' | 'neutral' }

const screenFromPath = (): Screen => {
  const path = window.location.pathname
  const routes: Record<string, Screen> = {
    '/': 'public',
    '/membership': 'request',
    '/admin': 'admin',
    '/admin/members': 'members',
    '/admin/memberships': 'memberships',
    '/admin/payments': 'payments',
    '/admin/attendance': 'attendance',
    '/admin/leads': 'leads',
    '/admin/reports': 'reports',
    '/member': 'member-portal',
    '/member/attendance': 'member-attendance',
    '/member/payments': 'member-payments',
    '/member/membership': 'member-membership',
  }
  return routes[path] || 'public'
}

const pathForScreen = (screen: Screen) => {
  const routes: Record<Screen, string> = {
    public: '/', request: '/membership', admin: '/admin', members: '/admin/members', memberships: '/admin/memberships',
    payments: '/admin/payments', attendance: '/admin/attendance', leads: '/admin/leads', reports: '/admin/reports',
    'member-portal': '/member', 'member-attendance': '/member/attendance', 'member-payments': '/member/payments', 'member-membership': '/member/membership',
  }
  return routes[screen]
}

