function Icon({ children }: { children: ReactNode }) { return <span className="icon" aria-hidden="true">{children}</span> }
function StatusBadge({ status }: { status: string }) { return <span className={`badge badge-${status.replaceAll(' ', '-')}`}>{status}</span> }
function Avatar({ member, size = 'md' }: { member: Member; size?: 'sm' | 'md' | 'lg' }) { return <div className={`avatar avatar-${size}`}>{member.avatar}</div> }
function Button({ children, variant = 'primary', onClick, type = 'button', full = false }: { children: ReactNode; variant?: 'primary' | 'ghost' | 'dark' | 'danger'; onClick?: () => void; type?: 'button' | 'submit'; full?: boolean }) { return <button type={type} onClick={onClick} className={`button button-${variant}${full ? ' button-full' : ''}`}>{children}</button> }
function PageHeader({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) { return <div className="page-header"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{description && <p>{description}</p>}</div>{action && <div className="header-action">{action}</div>}</div> }
function EmptyState({ title = 'موردی پیدا نشد', description = 'با تغییر فیلتر یا جستجو دوباره امتحان کنید.' }: { title?: string; description?: string }) { return <div className="empty-state"><div className="empty-icon">⌁</div><h3>{title}</h3><p>{description}</p></div> }

function PublicNav({ onNavigate, onDemo, onRequest }: { onNavigate: (screen: Screen) => void; onDemo: () => void; onRequest: () => void }) {
  return <header className="public-nav"><div className="brand-lockup"><div className="brand-mark">FL</div><div><strong>Fit Land Gym</strong><span>باشگاه بدنسازی آقایان</span></div></div><nav><button onClick={() => onNavigate('public')}>خانه</button><button onClick={() => document.getElementById('facilities')?.scrollIntoView({ behavior: 'smooth' })}>امکانات</button><button onClick={() => document.getElementById('membership')?.scrollIntoView({ behavior: 'smooth' })}>تعرفه‌ها</button><button onClick={() => document.getElementById('faq')?.scrollIntoView({ behavior: 'smooth' })}>سوالات متداول</button></nav><div className="nav-actions"><button className="text-button" onClick={onDemo}>ورود به Demo</button><Button onClick={onRequest}>شروع عضویت <span>←</span></Button></div></header>
}

